from collections import deque

def transform(grid):
    a=[row[:] for row in grid]; h=len(a); w=len(a[0])
    nbr4=[(-1,0),(1,0),(0,-1),(0,1)]
    nbr8=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
    # label 1-components
    ones=set((r,c) for r in range(h) for c in range(w) if a[r][c]==1)
    comps=[]
    seen=set()
    for cell in ones:
        if cell in seen: continue
        q=[cell]; seen.add(cell); comp=set()
        while q:
            r,c=q.pop(); comp.add((r,c))
            for dr,dc in nbr4:
                z=(r+dr,c+dc)
                if z in ones and z not in seen: seen.add(z); q.append(z)
        comps.append(comp)
    # zero components under 4-connectivity
    zeros=set((r,c) for r in range(h) for c in range(w) if a[r][c]==0)
    zcomps=[]; seen=set()
    for cell in zeros:
        if cell in seen: continue
        q=[cell]; seen.add(cell); comp=set()
        while q:
            r,c=q.pop(); comp.add((r,c))
            for dr,dc in nbr4:
                z=(r+dr,c+dc)
                if 0<=z[0]<h and 0<=z[1]<w and z in zeros and z not in seen: seen.add(z); q.append(z)
        zcomps.append(comp)
    hole_comps=[z for z in zcomps if not any(r==0 or c==0 or r==h-1 or c==w-1 for r,c in z)]
    # identify 1-components touching an enclosed zero component, 3-shell enclosed and 2-shell exterior
    eligible=set()
    for comp in comps:
        if any((r+dr,c+dc) in hole for r,c in comp for dr,dc in nbr4 for hole in hole_comps):
            eligible |= comp
    # set 3 on 8-neighbor shell of enclosed zero regions
    for hole in hole_comps:
        for r,c in hole:
            if any(0<=r+dr<h and 0<=c+dc<w and a[r+dr][c+dc]==1 for dr,dc in nbr8): a[r][c]=3
    # set 2 on exterior zeros 8-adjacent to eligible 1s
    for r in range(h):
        for c in range(w):
            if a[r][c]==0 and any(0<=r+dr<h and 0<=c+dc<w and (r+dr,c+dc) in eligible for dr,dc in nbr8): a[r][c]=2
    return a

