src='''from collections import deque


def transform(grid):
    """Color the one-cell rims of enclosed zero regions and their outer rims."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    n4 = ((-1, 0), (1, 0), (0, -1), (0, 1))
    n8 = tuple((dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
               if dr != 0 or dc != 0)

    # Label each 4-connected component of 1s.
    one_label = {}
    next_label = 0
    for r in range(h):
        for c in range(w):
            if out[r][c] != 1 or (r, c) in one_label:
                continue
            stack = [(r, c)]
            one_label[(r, c)] = next_label
            while stack:
                y, x = stack.pop()
                for dy, dx in n4:
                    z = (y + dy, x + dx)
                    if (0 <= z[0] < h and 0 <= z[1] < w
                            and out[z[0]][z[1]] == 1 and z not in one_label):
                        one_label[z] = next_label
                        stack.append(z)
            next_label += 1

    # Find 4-connected zero regions. A region not touching the grid edge is a hole.
    unseen = {(r, c) for r in range(h) for c in range(w) if out[r][c] == 0}
    holes = []
    outside = []
    while unseen:
        start = unseen.pop()
        stack = [start]
        region = {start}
        touches_edge = (start[0] == 0 or start[0] == h - 1 or
                        start[1] == 0 or start[1] == w - 1)
        while stack:
            y, x = stack.pop()
            for dy, dx in n4:
                z = (y + dy, x + dx)
                if z in unseen:
                    unseen.remove(z)
                    region.add(z)
                    stack.append(z)
                    if (z[0] == 0 or z[0] == h - 1 or
                            z[1] == 0 or z[1] == w - 1):
                        touches_edge = True
        (outside if touches_edge else holes).append(region)

    # A 1-component is active if it bounds at least one hole.
    active = set()
    for hole in holes:
        for r, c in hole:
            for dr, dc in n4:
                pos = (r + dr, c + dc)
                if pos in one_label:
                    active.add(one_label[pos])

    # Paint the inner one-cell rim of every hole with 3.
    for hole in holes:
        for r, c in hole:
            if any(0 <= r + dr < h and 0 <= c + dc < w
                   and out[r + dr][c + dc] == 1 for dr, dc in n8):
                out[r][c] = 3

    # Paint the outer one-cell rim of active 1-components with 2.
    for region in outside:
        for r, c in region:
            if any(0 <= r + dr < h and 0 <= c + dc < w
                   and one_label.get((r + dr, c + dc)) in active
                   for dr, dc in n8):
                out[r][c] = 2
    return out
'''
